const deepClone=x=>JSON.parse(JSON.stringify(x));
function initialState(){return {schema:2,planRevision:PLAN_REVISION,createdAt:new Date().toISOString(),workouts:deepClone(DEFAULT_WORKOUTS),sessions:{},nutrition:{},metrics:{},settings:{targets:deepClone(TARGETS),protein:170},baseline:deepClone(BASELINE),planArchives:[]}}
const E=document.getElementById('app');
let state=initialState(),page='dashboard',activeDay='mi',activeDate='',nutriDate='',progressExercise='wide_lat',modalDay='mi',modalIndex=-1,db=null,dbReady=false,saveHandle=0,saveChain=Promise.resolve(),toastHandle=0;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const weekday=date=>{const d=new Date(date+'T12:00:00');return (d.getDay()+6)%7};
const idFromDate=date=>DAY_IDS[weekday(date)];
const dateForNext=id=>{const d=new Date(today()+'T12:00:00');const n=(DAY_IDS.indexOf(id)-weekday(today())+7)%7;d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const pretty=date=>new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'long',year:'numeric'}).format(new Date((date||today())+'T12:00:00'));
const fmt=n=>(Number.isFinite(Number(n))?new Intl.NumberFormat('de-DE',{maximumFractionDigits:1}).format(Number(n)):'–');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=s=>esc(s);
const svg=(kind,size=20)=>{const paths={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',dumbbell:'<path d="m6.5 6.5 11 11M3 8l5-5M16 21l5-5M2 11l9-9M13 22l9-9"/>',food:'<path d="M4 3v7a4 4 0 0 0 4 4v7M8 3v18M12 3v7a4 4 0 0 1-4 4M17 3v18M17 3a4 4 0 0 1 4 4v7h-4"/>',chart:'<path d="M4 20V4M4 20h17M7 16l5-6 4 3 5-8"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M19 5l-1.5 1.5m-11 11L5 19"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',check:'<path d="m4 12 5 5 11-11"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="m5 12h14m-7-7 7 7-7 7"/>',scale:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M8 11a4 4 0 0 1 8 0m-4-2 2 4"/>',shield:'<path d="M12 2 4 5v6c0 5 4 9 8 11 4-2 8-6 8-11V5z"/><path d="m9 12 2 2 4-4"/>',edit:'<path d="m4 17 0 3h3l12-12-3-3zM14 7l3 3"/>',trash:'<path d="M4 7h16M8 7V4h8v3m-10 0 1 14h10l1-14"/>',note:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7z"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true">${paths[kind]||paths.home}</svg>`};
const NAV=[['dashboard','Übersicht','home'],['workout','Training','dumbbell'],['nutrition','Ernährung','food'],['progress','Fortschritt','chart'],['settings','Einstellungen','settings']];
async function openDatabase(){return new Promise((res,rej)=>{if(!('indexedDB' in window))return rej(new Error('IndexedDB unavailable'));const r=indexedDB.open('cablelog-private-v1',1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('app'))r.result.createObjectStore('app')};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
const idbGet=()=>new Promise((res,rej)=>{const tx=db.transaction('app','readonly');const r=tx.objectStore('app').get('state');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});
const idbPut=value=>new Promise((res,rej)=>{const tx=db.transaction('app','readwrite');tx.objectStore('app').put(value,'state');tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)});
async function loadState(){try{db=await openDatabase();dbReady=true;const saved=await idbGet();if(saved){state=JSON.parse(saved)}else{try{const fallback=localStorage.getItem('cablelog-state');if(fallback)state=JSON.parse(fallback)}catch{}}}catch(err){dbReady=false;try{const saved=localStorage.getItem('cablelog-state');if(saved)state=JSON.parse(saved)}catch{}}normalizeState()}
function normalizeState(){if(!state||typeof state!=='object')state=initialState();state.workouts=state.workouts||deepClone(DEFAULT_WORKOUTS);state.sessions=state.sessions||{};state.nutrition=state.nutrition||{};state.metrics=state.metrics||{};state.settings=state.settings||{targets:deepClone(TARGETS),protein:170};state.settings.targets=state.settings.targets||deepClone(TARGETS);state.baseline=state.baseline||deepClone(BASELINE);state.planArchives=state.planArchives||[];state.planRevision=state.planRevision||'1.1-legacy'}
function adoptPlanV12(){if(state.planRevision===PLAN_REVISION){showToast('Der aktuelle Plan ist bereits aktiviert.');return}if(!confirm('Trainingsplan 1.2 übernehmen? Vorher bitte ein JSON-Backup erstellen. Frühere Einträge und die bisherige Übungsstruktur werden im lokalen Archiv erhalten. Der aktuelle Trainingsplan wird ersetzt.'))return;
 const previous=deepClone(state.workouts);state.planArchives=state.planArchives||[];state.planArchives.push({savedAt:new Date().toISOString(),revision:state.planRevision,workouts:previous});
 for(const ses of Object.values(state.sessions)){if(!ses||!ses.day||ses.workoutSnapshot)continue;if(previous[ses.day])ses.workoutSnapshot=deepClone(previous[ses.day]);}
 const updated=deepClone(DEFAULT_WORKOUTS);
 // Benutzerdefinierte Medien nur übernehmen, wenn die Übungs-ID unverändert geblieben ist.
 for(const day of ['mo','mi','fr'])for(const ex of updated[day].exercises){const old=previous[day]?.exercises?.find(z=>z.id===ex.id);if(old?.media&&mediaPath(old.media))ex.media=old.media;}
 state.workouts={...state.workouts,...updated};state.planRevision=PLAN_REVISION;state.schema=2;progressExercise='wide_lat';queueSave();render();showToast('Trainingsplan 1.2 aktiviert. Frühere Einträge bleiben gespeichert.');}

function queueSave(){const indicator=document.getElementById('save-status');if(indicator)indicator.innerHTML='Speichert …';clearTimeout(saveHandle);saveHandle=setTimeout(flushSave,100)}
function flushSave(){clearTimeout(saveHandle);const snapshot=JSON.stringify(state);saveChain=saveChain.then(async()=>{try{if(dbReady)await idbPut(snapshot);else localStorage.setItem('cablelog-state',snapshot);const indicator=document.getElementById('save-status');if(indicator)indicator.innerHTML='<span class="green-dot"></span> Lokal gespeichert'}catch(err){console.error('Speicherfehler',err);const indicator=document.getElementById('save-status');if(indicator)indicator.textContent='Speichern fehlgeschlagen';showToast('Speichern fehlgeschlagen. Bitte Backup exportieren.')}});return saveChain}
function showToast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toastHandle);toastHandle=setTimeout(()=>el.classList.remove('visible'),2800)}
function renderNav(){const html=NAV.map(([id,label,ico])=>`<button class="nav-item ${page===id?'active':''}" type="button" data-action="page" data-page="${id}">${svg(ico)}<span>${label}</span></button>`).join('');document.getElementById('desktop-nav').innerHTML=html;document.getElementById('mobile-nav').innerHTML=html;document.getElementById('header-date').textContent=pretty(today())}
function cardMetric(label,value,hint,ico){return `<div class="card"><div class="metric"><div><div class="metric-label">${esc(label)}</div><div class="metric-value">${esc(value)}</div><div class="metric-hint">${esc(hint)}</div></div><div class="metric-ico">${svg(ico)}</div></div></div>`}
function weekStart(date){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()-weekday(date));return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function weekDates(date){const start=new Date(weekStart(date)+'T12:00:00');return DAY_IDS.map((_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`})}
function sessionKey(date,day){return `${date}_${day}`}
function getSession(date,day,create=false){const key=sessionKey(date,day);if(!state.sessions[key]&&create)state.sessions[key]={date,day,sets:{},note:'',completed:false,createdAt:new Date().toISOString()};return state.sessions[key]||null}
function allSessions(){return Object.values(state.sessions).filter(x=>x&&x.sets).sort((a,b)=>b.date.localeCompare(a.date))}
function sessionStats(s){if(!s)return {done:0,total:0};const w=s.workoutSnapshot||state.workouts[s.day];if(!w)return {done:0,total:0};let total=0,done=0;for(const ex of w.exercises){total+=ex.sets;for(const set of (s.sets[ex.id]||[]).slice(0,ex.sets)){if(set&&set.done)done++}}return {done,total}}
function lastSetWeight(ex,curDate){let best=null;for(const s of allSessions()){if(s.date>=curDate)continue;const records=s.sets[ex.id]||[];for(const item of records){if(item&&item.done&&item.weight!==''&&item.weight!=null&&Number.isFinite(Number(item.weight))){best={date:s.date,weight:item.weight,reps:records.filter(z=>z.done).map(z=>z.reps).join('/')};break}}if(best)break}return best||((state.baseline[ex.id]||{}).weight!=null?{date:null,...state.baseline[ex.id]}:null)}
function totalWeekSessions(){const week=weekStart(today());return allSessions().filter(s=>s.date>=week&&s.date<=today()&&(s.completed||sessionStats(s).done>0)).length}
function todayPlanName(){return TYPE[idFromDate(today())]}
function dashboard(){const nd=['mo','mi','fr'].map(id=>({id,date:dateForNext(id)})).sort((a,b)=>a.date.localeCompare(b.date))[0];const latest=allSessions().find(s=>sessionStats(s).done>0);const n=state.nutrition[today()]||{};const wc=weekDates(today());return `<div class="intro"><div><div class="eyebrow">TRAINING. DOKUMENTATION. FORTSCHRITT.</div><h1>Dein Training. Ein Ort.</h1><p>Trainingsplan, Satzprotokoll, Ernährung und Entwicklung – privat auf deinem Gerät gespeichert.</p></div><button class="button button-ghost" data-action="copy-report">${svg('copy',16)} Bericht kopieren</button></div>
 <section class="hero"><div><span class="pill">NÄCHSTE KRAFTEINHEIT · ${esc(DAY_NAMES[DAY_IDS.indexOf(nd.id)].toUpperCase())}</span><h2>${esc(state.workouts[nd.id].name)}</h2><p>${esc(state.workouts[nd.id].focus)} · ${state.workouts[nd.id].exercises.length} Übungen · Direkt zum Trainingsprotokoll.</p><button class="button button-primary" data-action="open-day" data-day="${nd.id}">${svg('arrow',16)} Training öffnen</button></div><div class="hero-visual">${svg('dumbbell',130)}</div></section>
 <div class="grid grid-4">${cardMetric('Krafttraining diese Woche',String(totalWeekSessions())+' / 3','Mo · Mi · Fr','dumbbell')}${cardMetric('Heutiges Kalorienziel',fmt(state.settings.targets[idFromDate(today())])+' kcal',todayPlanName(),'food')}${cardMetric('Proteinziel',fmt(state.settings.protein)+' g','Täglich','bolt')}${cardMetric('Protokollierte Einheiten',String(allSessions().filter(s=>sessionStats(s).done>0).length),'Lokal gespeichert','chart')}</div>
 <section class="section"><div class="section-head"><div><h2>Deine Trainingswoche</h2><p>Krafttraining und Fußball abgestimmt.</p></div></div><div class="week-grid">${wc.map((date,i)=>{const id=DAY_IDS[i];const isFit=['mo','mi','fr'].includes(id);const s=getSession(date,id);return `<button class="day-card ${date===today()?'today':''}" data-action="${isFit?'open-day':'open-nutrition-date'}" data-day="${id}" data-date="${date}"><small>${SHORT[i]} · ${date.slice(8,10)}.${date.slice(5,7)}.</small><b>${esc(TYPE[id])}</b><span class="type ${isFit?'':id==='sa'?'rest':'football'}">${isFit?'KRAFT':id==='sa'?'ERHOLUNG':'FUẞBALL'}</span><span class="day-dot" style="background:${s&&sessionStats(s).done>0?'var(--accent)':'#4b5d61'}"></span></button>`}).join('')}</div></section>
 <section class="section split"><div class="card"><div class="section-head"><h2>Letzte Trainingseinheit</h2><button class="text-button" data-action="page" data-page="progress">Verlauf ansehen →</button></div>${latest?`<div class="list-row"><div><div class="primary">${esc(TYPE[latest.day])} · ${pretty(latest.date)}</div><div class="secondary">${sessionStats(latest).done} absolvierte Sätze · ${esc(latest.note||'Kein Kommentar')}</div></div><span class="pill">Erfasst</span></div>`:`<div class="no-data">Noch keine datierte Einheit gespeichert. Deine zuletzt gemeldeten Mittwoch-Gewichte sind bereits als Ausgangswerte hinterlegt.</div>`}<div class="divider"></div><div class="section-head"><h2>Letzter Chat-Stand</h2></div>${[['lat','Einarmiger Latzug (alte Variante)'],['row','Einarmiges Rudern (alte Variante)'],['curl','Kabel-Bizepscurls (alte Variante)']].map(([id,label])=>{const x=state.baseline[id];return `<div class="list-row"><div><div class="primary">${esc(label)}</div><div class="secondary">${esc(x?.reps||'–')} Wiederholungen</div></div><strong>${fmt(x?.weight)} kg</strong></div>`}).join('')}<div class="note-line">Undatierte Ausgangswerte aus deinem Chat. Andere Varianten erhalten kein automatisch übernommenes Startgewicht.</div></div>
 <div class="card"><div class="section-head"><h2>Heute · Ernährung</h2><button class="text-button" data-action="page" data-page="nutrition">Eintragen →</button></div><div class="metric-value">${n.kcal!==undefined&&n.kcal!==''?fmt(n.kcal):'–'} <span class="muted" style="font-size:15px">/ ${fmt(state.settings.targets[idFromDate(today())])} kcal</span></div><div class="meter"><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,100*(Number(n.kcal)||0)/(state.settings.targets[idFromDate(today())]||1))}%"></div></div></div><div class="divider"></div><div class="list-row"><div class="primary">Protein</div><strong>${n.protein!==undefined&&n.protein!==''?fmt(n.protein):'–'} / ${fmt(state.settings.protein)} g</strong></div><div class="list-row"><div class="primary">Körpergewicht</div><strong>${state.metrics[today()]?.weight?fmt(state.metrics[today()].weight)+' kg':'–'}</strong></div><p class="section-subtitle" style="margin-top:18px">Kalorien und Protein trägst du nach deiner tatsächlichen Ernährung ein. Es erfolgt keine automatische Lebensmittelerkennung.</p></div></section>`}
function workout(){const w=state.workouts[activeDay],s=getSession(activeDate,activeDay);const done=s?sessionStats(s).done:0,total=w.exercises.reduce((a,x)=>a+x.sets,0);return `<div class="intro"><div><div class="eyebrow">TRAININGSPROTOKOLL</div><h1>Dein Krafttraining</h1><p>Jeden Satz direkt dokumentieren. Übungen und Wiederholungsbereiche kannst du jederzeit anpassen.</p></div><button class="button button-ghost" data-action="copy-report">${svg('copy',16)} Bericht kopieren</button></div>
 ${state.planRevision!==PLAN_REVISION?`<section class="notice" style="margin-bottom:18px"><strong>Neuer Trainingsplan verfügbar:</strong> 1.2 mit Preacher Curls, breitem Latzug, V-Griff-Rudern und einarmigen Trizeps-Pushdowns. <button class="button button-primary" data-action="adopt-plan" style="margin-top:10px">Trainingsplan 1.2 übernehmen</button></section>`:''}<div class="row space-between" style="flex-wrap:wrap;gap:12px"><div class="segmented">${['mo','mi','fr'].map(id=>`<button class="segment ${activeDay===id?'active':''}" data-action="select-day" data-day="${id}">${DAY_NAMES[DAY_IDS.indexOf(id)]}</button>`).join('')}</div><div class="date-control"><input aria-label="Datum der Trainingseinheit" type="date" id="workout-date" value="${attr(activeDate)}" /></div></div>
 <div class="workout-head"><div><div class="eyebrow">${esc(w.focus.toUpperCase())}</div><h2 style="margin-top:8px">${esc(w.name)}</h2><p class="section-subtitle">${w.exercises.length} Übungen · ${total} geplante Arbeitssätze · ${done} Sätze erledigt</p></div><div class="workout-info"><span>Fortschritt</span><strong id="workout-count">${done} / ${total}</strong></div></div><div class="progress-track" style="margin-bottom:20px"><div id="workout-progress" class="progress-fill" style="width:${Math.round(100*done/Math.max(total,1))}%"></div></div>
 ${w.exercises.map((ex,i)=>exerciseCard(ex,i,s)).join('')}
 <div class="card" style="margin-top:18px"><h2>Notizen zur Einheit</h2><p class="section-subtitle" style="margin-top:7px">Technik, Erholung, Beschwerden oder Änderungen dokumentieren.</p><textarea id="workout-note" rows="3" placeholder="z. B. gute Technik, letzte Wiederholung schwer …">${esc(s?.note||'')}</textarea><div class="row space-between" style="margin-top:16px;flex-wrap:wrap"><button class="button button-ghost" data-action="add-exercise">${svg('plus',16)} Übung hinzufügen</button><div class="row"><button class="button button-ghost" data-action="copy-report">${svg('copy',16)} Bericht</button><button class="button button-primary" data-action="finish-session">${svg('check',16)} Einheit abschließen</button></div></div></div><div class="notice" style="margin-top:13px">Gewicht = die an deinem Gerät eingestellte Masse. Das ist wegen der Umlenkrollen nicht zwingend identisch mit der Zugkraft am Griff. Für einarmige Übungen das Gewicht pro trainierter Seite erfassen.</div>`}
// Nur lokale Medien-Dateien. Keine fremden Bild-URLs, Tracker oder unsichere Pfade.
function mediaPath(value){const p=String(value||'').trim();return /^(?:media\/)?[a-zA-Z0-9][a-zA-Z0-9._-]*\.(?:gif|webp|mp4|webm)$/i.test(p)&&!p.includes('..')?p:''}
function exerciseMedia(ex,i){const path=mediaPath(ex.media);if(!path)return `<button type="button" class="text-button media-add" data-action="edit-exercise" data-index="${i}">+ Übungsanimation hinzufügen</button>`;const video=/\.(?:mp4|webm)$/i.test(path);return `<details class="exercise-media"><summary>▶ Animation ansehen</summary><div class="exercise-media-frame">${video?`<video src="${attr('./'+path)}" autoplay muted loop playsinline controls preload="metadata" aria-label="Animation ${attr(ex.name)}"></video>`:`<img src="${attr('./'+path)}" alt="Animierte Demonstration: ${attr(ex.name)}" loading="lazy">`}</div><p class="media-help">Achte auf eine zum eigenen Gerät passende Kabelführung und kontrollierte Bewegung.</p></details>`}
function exerciseCard(ex,i,s){const prev=lastSetWeight(ex,activeDate),sets=(s?.sets?.[ex.id]||[]);const repText=`${ex.sets} × ${ex.min}–${ex.max}`;return `<article class="exercise-card"><div class="exercise-head"><div class="exercise-title"><span class="exercise-no">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(ex.name)}</h3><p>${repText} Wiederholungen</p></div></div><div class="exercise-tools"><button type="button" class="icon-button" data-action="edit-exercise" data-index="${i}" title="Übung bearbeiten" aria-label="Übung bearbeiten">${svg('edit',16)}</button></div></div><div class="muscle"><strong>Muskel:</strong> ${esc(ex.muscle)}</div>${ex.tip?`<div class="tip">${esc(ex.tip)}</div>`:''}${exerciseMedia(ex,i)}${prev?`<div class="baseline">${prev.date?'Vorherige Einheit '+pretty(prev.date):'Aus deinem Chat übernommen'}: <strong>${fmt(prev.weight)} kg</strong> · ${esc(prev.reps||'–')} Wdh.</div>`:''}
 <div class="set-table"><div class="thead">Satz</div><div class="thead">Gewicht kg</div><div class="thead">Wdh.</div><div class="thead">RIR</div><div class="thead" style="text-align:center">OK</div>${Array.from({length:ex.sets},(_,j)=>{const v=sets[j]||{},weight=v.weight!==undefined?v.weight:(prev?.weight??ex.weight??'');return `<div class="set-n">${j+1}</div><input aria-label="Gewicht Satz ${j+1} ${attr(ex.name)}" type="number" min="0" step="0.5" inputmode="decimal" data-field="set" data-ex="${attr(ex.id)}" data-set="${j}" data-prop="weight" value="${attr(weight)}" placeholder="–"/><input aria-label="Wiederholungen Satz ${j+1} ${attr(ex.name)}" type="number" min="0" max="100" step="1" inputmode="numeric" data-field="set" data-ex="${attr(ex.id)}" data-set="${j}" data-prop="reps" value="${attr(v.reps??'')}" placeholder="–"/><input aria-label="RIR Satz ${j+1} ${attr(ex.name)}" type="number" min="0" max="10" step="1" inputmode="numeric" data-field="set" data-ex="${attr(ex.id)}" data-set="${j}" data-prop="rir" value="${attr(v.rir??'')}" placeholder="–"/><span class="checked"><input type="checkbox" aria-label="Satz ${j+1} erledigt ${attr(ex.name)}" data-field="set" data-ex="${attr(ex.id)}" data-set="${j}" data-prop="done" ${v.done?'checked':''}/></span>`}).join('')}</div></article>`}
function nutrition(){const d=nutriDate||today(),id=idFromDate(d),n=state.nutrition[d]||{},goal=state.settings.targets[id]||0,met=state.metrics[d]||{},meals=MEALS[id]||[];return `<div class="intro"><div><div class="eyebrow">ERNÄHRUNG · WOCHENPLAN</div><h1>Ernährung dokumentieren</h1><p>Die Mahlzeiten sind dein bestehender Wochenplan. Trage die tatsächlich konsumierten Tageswerte ein.</p></div></div><div class="row space-between" style="flex-wrap:wrap;gap:12px;margin-bottom:21px"><div class="pill pill-soft">${esc(TYPE[id])}</div><div class="date-control"><input id="nutrition-date" type="date" value="${attr(d)}" aria-label="Ernährungsdatum" /></div></div>
 <div class="grid grid-3">${cardMetric('Kalorienziel',fmt(goal)+' kcal',DAY_NAMES[DAY_IDS.indexOf(id)],'food')}${cardMetric('Proteinziel',fmt(state.settings.protein)+' g','Tagesziel','bolt')}${cardMetric('Eingetragene Mahlzeiten',String(Object.values(n.meals||{}).filter(Boolean).length)+' / '+meals.length,'Häkchen im Speiseplan','check')}</div>
 <section class="section split"><div class="card"><div class="section-head"><div><h2>Dein Speiseplan</h2><p>Gewichte wie in der bisherigen Planung; Nährwertangaben nicht automatisch berechnet.</p></div></div>${meals.map(([type,name,details],i)=>`<div class="meal"><input type="checkbox" aria-label="${attr(name)} gegessen" data-field="meal" data-meal="${i}" ${n.meals?.[i]?'checked':''}/><div class="meal-info"><small>${esc(type.toUpperCase())}</small><div><strong>${esc(name)}</strong></div><p>${esc(details)}</p></div></div>`).join('')}</div><div class="stack"><div class="card"><h2>Tatsächliche Tageswerte</h2><p class="section-subtitle" style="margin-top:8px">Manuell aus deiner Ernährungs-App oder Produktetiketten übernehmen.</p><div class="form-grid"><div class="field"><label for="n-kcal">Kalorien (kcal)</label><input id="n-kcal" type="number" inputmode="numeric" min="0" value="${attr(n.kcal??'')}" placeholder="z. B. 2680"/></div><div class="field"><label for="n-protein">Protein (g)</label><input id="n-protein" type="number" inputmode="decimal" min="0" step="0.1" value="${attr(n.protein??'')}" placeholder="z. B. 171"/></div><div class="field"><label for="n-water">Getränke (Liter)</label><input id="n-water" type="number" inputmode="decimal" min="0" step="0.1" value="${attr(n.water??'')}" placeholder="Optional"/></div><div class="field"><label for="m-weight">Körpergewicht (kg)</label><input id="m-weight" type="number" inputmode="decimal" min="0" step="0.1" value="${attr(met.weight??'')}" placeholder="Optional"/></div><div class="field"><label for="m-waist">Bauchumfang (cm)</label><input id="m-waist" type="number" inputmode="decimal" min="0" step="0.1" value="${attr(met.waist??'')}" placeholder="Optional"/></div></div><div class="field"><label for="n-note">Tagesnotiz</label><textarea id="n-note" rows="3" placeholder="Hunger, Sport, Besonderheiten …">${esc(n.note||'')}</textarea></div><button class="button button-primary" data-action="save-nutrition" style="width:100%">${svg('check',16)} Tageswerte speichern</button></div><div class="notice">Dein Fußballpensum ist hoch. Besonders vor Training und Spielen sind ausreichend Kohlenhydrate und Flüssigkeit wichtig. Die Tagesziele sind Ausgangswerte, keine gemessenen Energiebedarfe.</div></div></section>`}
function sparkline(points,unit){if(points.length<2)return '<div class="no-data">Für eine Verlaufsgrafik werden mindestens zwei datierte Einträge benötigt.</div>';const W=610,H=190,pad=30,vals=points.map(p=>p.value),min=Math.min(...vals),max=Math.max(...vals),rng=Math.max(1,max-min),coords=points.map((p,i)=>({x:pad+(W-pad*2)*(i/Math.max(1,points.length-1)),y:pad+(H-pad*2)*(1-(p.value-min)/rng),...p})),poly=coords.map(p=>`${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ');return `<div class="plot"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Verlauf von ${fmt(vals[0])} bis ${fmt(vals[vals.length-1])} ${esc(unit)}"><path d="M${pad} ${pad}H${W-pad}M${pad} ${H-pad}H${W-pad}" stroke="#2a3a3d" stroke-width="1"/><polyline points="${poly}" fill="none" stroke="#b9f66c" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>${coords.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4.5" fill="#b9f66c"><title>${esc(pretty(p.date))}: ${fmt(p.value)} ${esc(unit)}</title></circle>`).join('')}<text x="${pad}" y="${H-5}" font-size="10" fill="#91a2a8">${esc(points[0].date.slice(5))}</text><text text-anchor="end" x="${W-pad}" y="${H-5}" font-size="10" fill="#91a2a8">${esc(points[points.length-1].date.slice(5))}</text><text x="${pad}" y="18" font-size="11" fill="#b9f66c">${fmt(max)} ${esc(unit)}</text><text x="${pad}" y="${H-32}" font-size="11" fill="#91a2a8">${fmt(min)} ${esc(unit)}</text></svg><div class="plot-note">${points.length} Messpunkte · Manuell erfasste Werte · Keine automatische Cloud-Synchronisierung</div></div>`}
function progress(){const ids=[...new Map(Object.values(state.workouts).flatMap(w=>w.exercises).map(e=>[e.id,e])).values()];const ex=ids.find(x=>x.id===progressExercise)||ids[0];const sessions=allSessions().slice().reverse();const records=sessions.map(s=>{const done=(s.sets[ex.id]||[]).filter(x=>x.done&&Number.isFinite(Number(x.weight))&&x.weight!=='');return done.length?{date:s.date,value:Math.max(...done.map(x=>Number(x.weight))),reps:done.map(x=>x.reps).join('/')}:null}).filter(Boolean);const weights=Object.entries(state.metrics).filter(([k,v])=>v.weight&&Number(v.weight)>0).map(([date,v])=>({date,value:Number(v.weight)})).sort((a,b)=>a.date.localeCompare(b.date));const waist=Object.entries(state.metrics).filter(([k,v])=>v.waist&&Number(v.waist)>0).map(([date,v])=>({date,value:Number(v.waist)})).sort((a,b)=>a.date.localeCompare(b.date));return `<div class="intro"><div><div class="eyebrow">VERLAUF & ANALYSE</div><h1>Deine Fortschritte</h1><p>Gewichtsentwicklung pro Übung, Körpergewicht und Umfang auf Basis deiner gespeicherten Einträge.</p></div></div>
 <div class="grid grid-3">${cardMetric('Erfasste Trainings',String(sessions.filter(s=>sessionStats(s).done>0).length),'Mit mindestens einem erledigten Satz','dumbbell')}${cardMetric('Gewichtsmessungen',String(weights.length),'In der Ernährungsübersicht','scale')}${cardMetric('Übungen im Plan',String(ids.length),'Über 3 Trainingstage','chart')}</div>
 <section class="section"><div class="card"><div class="section-head"><div><h2>Entwicklung einer Übung</h2><p>Höchstes dokumentiertes Stackgewicht je Einheit.</p></div></div><div class="field"><label for="progress-exercise">Übung wählen</label><select id="progress-exercise">${ids.map(x=>`<option value="${attr(x.id)}" ${x.id===ex.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>${sparkline(records,'kg')}${records.length?`<div class="card-list" style="margin-top:17px">${records.slice(-8).reverse().map(r=>`<div class="list-row"><div><div class="primary">${pretty(r.date)}</div><div class="secondary">${esc(r.reps)} Wdh.</div></div><strong>${fmt(r.value)} kg</strong></div>`).join('')}</div>`:`<div class="baseline">Aus deinem Chat liegt ein undatierter letzter Stand vor${state.baseline[ex.id]?.weight!=null?`: ${fmt(state.baseline[ex.id].weight)} kg · ${esc(state.baseline[ex.id].reps)}`:'.'} Er wird nicht als historischer Messpunkt ausgegeben.</div>`}</div></section>
 <section class="section grid grid-2"><div class="card"><div class="section-head"><h2>Körpergewicht</h2></div>${sparkline(weights,'kg')}</div><div class="card"><div class="section-head"><h2>Bauchumfang</h2></div>${sparkline(waist,'cm')}</div></section><div class="notice" style="margin-top:18px">Die eingestellte Steckgewicht-Masse hängt von der Übersetzung deines Cable Crossovers ab. Vergleiche deshalb dieselbe Übung an derselben Station, nicht unterschiedliche Maschinen oder Griffkonfigurationen miteinander.</div>`}
function settings(){const count=allSessions().length;return `<div class="intro"><div><div class="eyebrow">DATEN & EINSTELLUNGEN</div><h1>Deine Daten bleiben bei dir</h1><p>Ohne Konto, ohne Server, ohne Tracking. Speichern erfolgt lokal im Browser auf diesem Gerät.</p></div></div><section class="grid grid-2"><div class="card"><div class="row"><div class="metric-ico">${svg('shield')}</div><div><h2>Private Datenspeicherung</h2><p class="section-subtitle">Primär IndexedDB. Bei nicht unterstützten Dateiaufrufen kann ein lokaler Browser-Speicher als Ausweichlösung dienen.</p></div></div><div class="divider"></div><div class="list-row"><div class="primary">Gespeicherte Einheiten</div><strong>${count}</strong></div><div class="list-row"><div class="primary">Speicherort</div><strong>Dieses Gerät</strong></div><div class="list-row"><div class="primary">Version</div><strong>${APP_VERSION}</strong></div><p class="section-subtitle" style="margin-top:17px">Beim Löschen der Browser-Website-Daten oder Gerätewechsel können Einträge verloren gehen. Erstelle regelmäßig eine Sicherungsdatei.</p></div>
 <div class="card"><h2>Backup und ChatGPT</h2><p class="section-subtitle" style="margin-top:8px">Übertrage Daten zwischen Geräten oder in diesen Chat. Es wird nichts automatisch gesendet.</p><div class="stack" style="margin-top:16px"><button class="button button-primary" data-action="export">${svg('download',17)} Gesamtes Backup als JSON</button><button class="button button-ghost" data-action="import">${svg('download',17)} Backup importieren</button><button class="button button-ghost" data-action="copy-report">${svg('copy',17)} Trainingsbericht für ChatGPT kopieren</button></div><div class="notice" style="margin-top:17px">ChatGPT kann deine lokalen Browserdaten nicht automatisch einsehen. Du kannst den kopierten Trainingsbericht hier einfügen oder die JSON-Datei hochladen.</div></div></section>
 <section class="section"><div class="card"><h2>Trainingsplan-Version</h2><p class="section-subtitle" style="margin-top:8px">Aktiver Plan: ${esc(state.planRevision===PLAN_REVISION?'1.2 – aktueller Plan':'1.1 / individuell bearbeitet')}. ${state.planArchives.length} archivierte Planversion(en). Die bestehenden Trainings-, Ernährungs- und Körperdaten bleiben auf diesem Gerät erhalten.</p>${state.planRevision!==PLAN_REVISION?`<button class="button button-primary" data-action="adopt-plan" style="margin-top:12px">Trainingsplan 1.2 übernehmen</button><p class="section-subtitle">Bitte vorher ein JSON-Backup exportieren. Der aktuelle Plan wird archiviert und die neue Übungsliste aktiviert.</p>`:'<p class="section-subtitle">Plan 1.2 ist bereits aktiviert. Alte Trainingsvarianten werden nicht mit neuen Übungen vermischt.</p>'}</div></section><section class="section"><div class="card"><h2>Kalorien- und Proteinziele</h2><p class="section-subtitle" style="margin:8px 0">Persönliche Startwerte nach Belastung. Du kannst sie anpassen.</p><div class="grid grid-4" style="margin-top:16px">${DAY_IDS.map((id,i)=>`<div class="field" style="margin:0"><label for="target-${id}">${SHORT[i]} · kcal</label><input id="target-${id}" data-field="goal" data-day="${id}" type="number" min="0" max="10000" value="${attr(state.settings.targets[id]??TARGETS[id])}"/></div>`).join('')}</div><div class="field" style="max-width:250px"><label for="protein-goal">Protein täglich (g)</label><input id="protein-goal" type="number" min="0" max="500" value="${attr(state.settings.protein)}" /></div><button class="button button-primary" data-action="save-goals">Ziele speichern</button></div></section>
 <section class="section"><div class="card"><h2>Trainingsplan bearbeiten</h2><p class="section-subtitle" style="margin-top:8px">Übungen, Anzahl der Sätze und Wiederholungsbereiche kannst du im Tab „Training“ direkt über das Stiftsymbol bearbeiten oder neue Übungen hinzufügen.</p><div class="divider"></div><h2 style="color:#e4abad">Daten löschen</h2><p class="section-subtitle" style="margin-top:8px">Löscht alle gespeicherten Einträge auf diesem Gerät und stellt den Ausgangsplan wieder her.</p><button class="button button-danger" data-action="reset-all">${svg('trash',16)} Alle lokalen Daten löschen</button></div></section>`}
function render(){renderNav();E.innerHTML=({dashboard,workout,nutrition,progress,settings}[page]||dashboard)();document.title=`${NAV.find(x=>x[0]===page)?.[1]||'CABLE / LOG'} · CABLE / LOG`}
function switchPage(next){page=next;render();window.scrollTo({top:0,behavior:'instant'})}
function updateWorkoutProgress(){const s=getSession(activeDate,activeDay);const w=state.workouts[activeDay];const total=w.exercises.reduce((n,e)=>n+e.sets,0),done=sessionStats(s).done;const c=document.getElementById('workout-count');if(c)c.textContent=`${done} / ${total}`;const p=document.getElementById('workout-progress');if(p)p.style.width=`${Math.round(100*done/Math.max(total,1))}%`}
function handleSetInput(el){const exId=el.dataset.ex,num=Number(el.dataset.set),prop=el.dataset.prop;const s=getSession(activeDate,activeDay,true);s.sets[exId]=s.sets[exId]||[];s.sets[exId][num]=s.sets[exId][num]||{weight:'',reps:'',rir:'',done:false};const obj=s.sets[exId][num];obj[prop]=prop==='done'?el.checked:el.value;queueSave();if(prop==='done')updateWorkoutProgress()}
function handleMeal(el){const d=nutriDate||today(),n=state.nutrition[d]||{meals:{}};n.meals=n.meals||{};n.meals[el.dataset.meal]=el.checked;state.nutrition[d]=n;queueSave();render()}
function editExercise(i){modalIndex=i;modalDay=activeDay;const ex=i>=0?state.workouts[activeDay].exercises[i]:{name:'',muscle:'',sets:3,min:8,max:12,weight:'',tip:'',media:''};document.getElementById('dialog-title').textContent=i>=0?'Übung bearbeiten':'Neue Übung hinzufügen';document.getElementById('delete-exercise').style.display=i>=0?'inline-flex':'none';const f=document.getElementById('exercise-form');for(const k of ['name','muscle','sets','min','max','weight','tip','media'])f.elements[k].value=ex[k]??'';document.getElementById('exercise-dialog').showModal()}
function saveExercise(){const f=document.getElementById('exercise-form');const val=k=>f.elements[k].value.trim(),s=Number(val('sets')),mi=Number(val('min')),ma=Number(val('max'));if(!val('name')||s<1||s>12||mi<1||mi>ma||ma>100){showToast('Bitte gültigen Übungsnamen und Wiederholungsbereich eingeben.');return}if(val('media')&&!mediaPath(val('media'))){showToast('Bitte einen lokalen Dateinamen angeben, z. B. media/latzug.gif');return}const ex={id:modalIndex>=0?state.workouts[modalDay].exercises[modalIndex].id:'custom_'+Date.now(),name:val('name'),muscle:val('muscle'),sets:s,min:mi,max:ma,weight:val('weight')===''?null:Number(val('weight')),tip:val('tip'),media:mediaPath(val('media'))};const arr=state.workouts[modalDay].exercises;if(modalIndex>=0)arr[modalIndex]=ex;else arr.push(ex);queueSave();document.getElementById('exercise-dialog').close();render();showToast('Trainingsplan aktualisiert.')}
function deleteExercise(){if(modalIndex<0)return;const arr=state.workouts[modalDay].exercises;const ex=arr[modalIndex];if(!confirm('Übung "'+ex.name+'" aus dem Trainingsplan entfernen? Frühere Protokolle bleiben im Backup erhalten.'))return;arr.splice(modalIndex,1);document.getElementById('exercise-dialog').close();queueSave();render();showToast('Übung entfernt.')}
function saveNutrition(){const d=nutriDate||today(),n=state.nutrition[d]||{},m=state.metrics[d]||{};for(const [field,id] of [['kcal','n-kcal'],['protein','n-protein'],['water','n-water']])n[field]=document.getElementById(id).value;n.note=document.getElementById('n-note').value;for(const [field,id] of [['weight','m-weight'],['waist','m-waist']])m[field]=document.getElementById(id).value;state.nutrition[d]=n;state.metrics[d]=m;queueSave();showToast('Tageswerte gespeichert.')}
function saveGoals(){DAY_IDS.forEach(id=>{const v=Number(document.getElementById('target-'+id).value);if(Number.isFinite(v)&&v>=0)state.settings.targets[id]=v});const protein=Number(document.getElementById('protein-goal').value);if(Number.isFinite(protein)&&protein>=0)state.settings.protein=protein;queueSave();showToast('Ziele gespeichert.')}
function finishSession(){const s=getSession(activeDate,activeDay,true);const stats=sessionStats(s);if(stats.done===0){showToast('Bitte zuerst absolvierte Sätze markieren.');return}const note=document.getElementById('workout-note');if(note)s.note=note.value;s.completed=true;s.completedAt=new Date().toISOString();queueSave();showToast('Trainingseinheit abgeschlossen.');render()}
function buildReport(){let lines=['# CABLE / LOG – Trainingsbericht',`Erstellt: ${pretty(today())}`,`Auswertungsgrundlage: auf dem Gerät erfasste Einträge. Ausgangswerte ohne Trainingsdatum sind separat gekennzeichnet.`, ''];for(const day of ['mo','mi','fr']){const w=state.workouts[day];lines.push(`## ${DAY_NAMES[DAY_IDS.indexOf(day)]} – ${TYPE[day]}`,`${w.name}`);const sessions=allSessions().filter(s=>s.day===day&&sessionStats(s).done>0);const s=sessions[0];if(s)lines.push(`Letzte protokollierte Einheit: ${s.date}${s.completed?' (abgeschlossen)':''}`);else lines.push('Noch keine datierte Einheit erfasst.');w.exercises.forEach((ex,i)=>{let result='–';if(s){const sets=s.sets[ex.id]||[];const filtered=sets.filter(z=>z?.done);if(filtered.length)result=filtered.map(z=>`${z.weight||'?'} kg × ${z.reps||'?'} Wdh.${z.rir!==''&&z.rir!=null?' (RIR '+z.rir+')':''}`).join(' | ')}else if(day==='mi'&&state.baseline[ex.id])result=`Aus Chat (ohne Datum): ${state.baseline[ex.id].weight} kg, ${state.baseline[ex.id].reps} Wdh.`;lines.push(`${i+1}. ${ex.name} (${ex.sets} × ${ex.min}–${ex.max}): ${result}`)});if(s?.note)lines.push(`Notiz: ${s.note}`);lines.push('')}const dates=Object.keys(state.nutrition).sort().slice(-7);if(dates.length){lines.push('## Ernährung – letzte Einträge');dates.forEach(d=>{const n=state.nutrition[d];lines.push(`${d}: ${n.kcal||'–'} kcal, ${n.protein||'–'} g Protein${n.note?' | '+n.note:''}`)})}if(state.planArchives?.length){lines.push('','## Archiv frühere Übungsvarianten');for(const a of state.planArchives.slice(-2)){lines.push(`Archiviert: ${a.savedAt} (Plan ${a.revision||'vorherig'})`);for(const d of ['mo','mi','fr']){const old=a.workouts?.[d];if(old)lines.push(`${DAY_NAMES[DAY_IDS.indexOf(d)]}: ${old.exercises.map(e=>e.name).join('; ')}`)}}}lines.push('','Hinweis: Bei Gewichten handelt es sich um ausgewählte Stackgewichte; tatsächlicher Widerstand wegen Umlenkung unbekannt.');return lines.join('\n')}
async function copyReport(){const content=buildReport();try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(content);else throw Error('clipboard unavailable');showToast('Trainingsbericht kopiert. Hier in ChatGPT einfügen.')}catch{const ta=document.createElement('textarea');ta.value=content;ta.style.position='fixed';ta.style.top='-2000px';document.body.appendChild(ta);ta.select();const success=document.execCommand('copy');ta.remove();if(success)showToast('Trainingsbericht kopiert.');else{const blob=new Blob([content],{type:'text/plain;charset=utf-8'});downloadFile(blob,'cable-log-chatgpt-bericht.txt');showToast('Kopieren nicht möglich – Bericht heruntergeladen.')}}}
function downloadFile(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function exportState(){flushSave();const blob=new Blob([JSON.stringify({app:'CABLE / LOG',version:APP_VERSION,exportedAt:new Date().toISOString(),data:state},null,2)],{type:'application/json;charset=utf-8'});downloadFile(blob,'cable-log-backup-'+today()+'.json');showToast('Backup erstellt. Bitte sicher aufbewahren.')}
async function importState(file){if(!file)return;try{const text=await file.text(),obj=JSON.parse(text),data=obj.data||obj;if(!data||!data.workouts||!data.sessions||!data.nutrition||!data.settings)throw Error('Ungültiges Datenformat');if(!confirm('Das Backup ersetzt alle aktuell lokal gespeicherten Einträge. Fortfahren?'))return;state=data;normalizeState();await flushSave();render();showToast('Backup erfolgreich importiert.')}catch(err){showToast('Import fehlgeschlagen: keine gültige Sicherungsdatei.')}}
function resetAll(){if(!confirm('Wirklich alle lokalen Trainings-, Ernährungs- und Messdaten löschen? Dieser Schritt ist nicht rückgängig zu machen.'))return;if(!confirm('Letzte Bestätigung: Alle lokalen Daten löschen und Ausgangsplan wiederherstellen?'))return;state=initialState();flushSave();render();showToast('Lokale Daten zurückgesetzt.')}
function actionClick(el){const a=el.dataset.action;if(a==='page')switchPage(el.dataset.page);else if(a==='open-day'){activeDay=el.dataset.day;activeDate=el.dataset.date||dateForNext(activeDay);switchPage('workout')}else if(a==='open-nutrition-date'){nutriDate=el.dataset.date||today();switchPage('nutrition')}else if(a==='select-day'){activeDay=el.dataset.day;activeDate=dateForNext(activeDay);render()}else if(a==='copy-report')copyReport();else if(a==='export')exportState();else if(a==='import')document.getElementById('import-file').click();else if(a==='finish-session')finishSession();else if(a==='save-nutrition')saveNutrition();else if(a==='save-goals')saveGoals();else if(a==='edit-exercise')editExercise(Number(el.dataset.index));else if(a==='add-exercise')editExercise(-1);else if(a==='close-dialog')document.getElementById('exercise-dialog').close();else if(a==='delete-exercise')deleteExercise();else if(a==='reset-all')resetAll();else if(a==='adopt-plan')adoptPlanV12()}
document.addEventListener('click',event=>{const btn=event.target.closest('[data-action]');if(btn)actionClick(btn)});
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.field==='set'&&el.type!=='checkbox')handleSetInput(el);if(el.id==='workout-note'){getSession(activeDate,activeDay,true).note=el.value;queueSave()}if(['n-kcal','n-protein','n-water','n-note'].includes(el.id)){const key={'n-kcal':'kcal','n-protein':'protein','n-water':'water','n-note':'note'}[el.id],n=state.nutrition[nutriDate]||{meals:{}};n[key]=el.value;state.nutrition[nutriDate]=n;queueSave()}if(['m-weight','m-waist'].includes(el.id)){const key=el.id==='m-weight'?'weight':'waist',m=state.metrics[nutriDate]||{};m[key]=el.value;state.metrics[nutriDate]=m;queueSave()}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.field==='set'&&el.type==='checkbox')handleSetInput(el);else if(el.dataset.field==='meal')handleMeal(el);else if(el.id==='workout-date'){activeDate=el.value||today();render()}else if(el.id==='nutrition-date'){nutriDate=el.value||today();render()}else if(el.id==='progress-exercise'){progressExercise=el.value;render()}});
document.getElementById('exercise-form').addEventListener('submit',event=>{event.preventDefault();saveExercise()});
document.getElementById('import-file').addEventListener('change',event=>{importState(event.target.files[0]);event.target.value=''});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flushSave()});
async function init(){activeDay=['mo','mi','fr'].map(id=>({id,date:dateForNext(id)})).sort((a,b)=>a.date.localeCompare(b.date))[0].id;activeDate=dateForNext(activeDay);nutriDate=today();await loadState();render();if(location.protocol==='https:'||location.hostname==='localhost'){if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(err=>console.warn('Offline service worker:',err))}}}
init();
